{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C11"],
      "claim": "Lu 25-109, a close analog with an N-methyl-tetrahydropyridine attached to a heteroaromatic ring, entered the brain in a 1:1 ratio with blood in rat microdialysis, directly supporting meaningful CNS access for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "1-[11C]methyl-4-phenoxy-1,2,3,6-tetrahydropyridine freely crossed the BBB in rodents and non-human primates after i.v. injection, supporting the N-methyl-tetrahydropyridyl ether scaffold of the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Lu 25-077, the N-demethylated analog of Lu 25-109, also entered the brain in a 1:1 ratio with blood in rat microdialysis, showing that this tetrahydropyridyl-heteroaryl motif penetrates the CNS even without N-methylation.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "[11C]PMP, an N-[11C]methyl piperidine ester, showed high initial brain uptake (~10% injected dose/g in cortex) in mice, supporting good CNS access for basic N-methyl saturated heterocycles.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "[18F]MC225, a weak P-gp substrate, still showed relatively high brain uptake at baseline in rats, indicating that moderate efflux liability does not preclude meaningful CNS access.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Multiple high-transfer analogs sharing the N-methyl-tetrahydropyridyl heteroaryl/ether motif show direct brain penetration, including 1:1 brain:blood ratios and free BBB crossing, while the query's favorable passive properties support meaningful CNS access; moderate efflux risk is not disqualifying.",
  "evidence_gaps": [
    "No direct brain/plasma or CSF measurement exists for the exact query molecule.",
    "Efflux transporter liability of the query was not directly measured.",
    "Metabolic stability of the hexyloxy-thiadiazole moiety is unknown, though it does not determine the CNS-access label."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

